Columns, in this order: student `name`, course `title`, status.
Sort by student `name` ascending, then by course `title` ascending.', 'CREATE TABLE students (
    id         INTEGER PRIMARY KEY,
    name       TEXT NOT NULL,
    city       TEXT,
    birth_year INTEGER NOT NULL
);
