Columns, in this order: course `title`, student `name`, `grade`.
Sort by course `title` ascending, then student `name` ascending.', 'CREATE TABLE students (
    id         INTEGER PRIMARY KEY,
    name       TEXT NOT NULL,
    city       TEXT,
    birth_year INTEGER NOT NULL
);
CREATE TABLE courses (
    id      INTEGER PRIMARY KEY,
    title   TEXT NOT NULL,
    credits INTEGER NOT NULL,
    teacher TEXT
);
