6          | 3         | 19.0 
7          | 1         | 10.5', NULL, 'ordered', NULL, '`RANK() OVER (PARTITION BY course_id ORDER BY grade DESC)` in a subquery or CTE, then keep rank 1. `ROW_NUMBER()` would keep only one student in case of a tie.', NULL, 'sql', 'sql-best-per-course', 2.0, 'WITH ranked AS (
  SELECT e.course_id, e.student_id, e.grade,
         RANK() OVER (PARTITION BY e.course_id ORDER BY e.grade DESC) AS rk
  FROM enrollments e
  WHERE e.grade IS NOT NULL
)
