INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, alternatives, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at, signature, skills) VALUES (NULL, 'seed', 'sql', 'hard', 'fr', NULL, 'Top 2 par catégorie', 'Pour chaque catégorie, renvoyez ses 2 produits les plus chers (moins si la catégorie en a moins). À prix égal, le produit dont le `name` vient en premier dans l''ordre alphabétique gagne. Au plus 2 produits par catégorie, même en cas d''égalité.
Colonnes, dans cet ordre : `category`, `name`, `price`.
Triez par `category` croissant, puis `price` décroissant, puis `name` croissant.', 'CREATE TABLE customers (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    city TEXT NOT NULL
);
CREATE TABLE products (
    id       INTEGER PRIMARY KEY,
    name     TEXT NOT NULL,
    category TEXT NOT NULL,
    price    REAL NOT NULL
);
CREATE TABLE orders (
    id          INTEGER PRIMARY KEY,
    customer_id INTEGER REFERENCES customers(id),
    order_date  TEXT NOT NULL
);
CREATE TABLE order_items (
    order_id   INTEGER NOT NULL REFERENCES orders(id),
    product_id INTEGER NOT NULL REFERENCES products(id),
    qty        INTEGER NOT NULL,
    PRIMARY KEY (order_id, product_id)
);

