INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, alternatives, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at, signature, skills) VALUES (NULL, 'seed', 'sql', 'hard', 'en', NULL, 'Daily revenue and running total', 'The revenue of a day is the sum of `qty * price` of all the items of all the orders of that day. For each day that has at least one ordered item, return the revenue of the day and the running total (sum of the revenues of that day and all previous days).
Columns, in this order: `order_date`, day revenue, running total.
Sort by `order_date` ascending.', 'CREATE TABLE customers (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    city TEXT NOT NULL
);
CREATE TABLE products (
    id       INTEGER PRIMARY KEY,
    name     TEXT NOT NULL,
    category TEXT NOT NULL,
    price    REAL NOT NULL
);
CREATE TABLE orders (
    id          INTEGER PRIMARY KEY,
    customer_id INTEGER REFERENCES customers(id),
    order_date  TEXT NOT NULL
);
CREATE TABLE order_items (
    order_id   INTEGER NOT NULL REFERENCES orders(id),
    product_id INTEGER NOT NULL REFERENCES products(id),
    qty        INTEGER NOT NULL,
    PRIMARY KEY (order_id, product_id)
);

