2        | 5          | 1  
3        | 3          | 1  
3        | 1          | 1  
4        | 11         | 3  
5        | 8          | 1  
5        | 9          | 1  
6        | 10         | 1  
6        | 4          | 2', NULL, 'ordered', NULL, 'First aggregate per day (`GROUP BY order_date`, in a CTE), then `SUM(revenue) OVER (ORDER BY order_date)`. Several orders can share the same day!', NULL, 'sql', 'sql-daily-running-total', 2.0, 'WITH daily AS (
  SELECT o.order_date, SUM(oi.qty * p.price) AS revenue
  FROM orders o
  JOIN order_items oi ON oi.order_id = o.id
  JOIN products p ON p.id = oi.product_id
  GROUP BY o.order_date
)
SELECT order_date, revenue, SUM(revenue) OVER (ORDER BY order_date) AS running
FROM daily
ORDER BY order_date', 'active', 'seed', 1791475200, NULL, 'sql');
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, alternatives, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at, signature, skills) VALUES (NULL, 'seed', 'sql', 'hard', 'fr', NULL, 'Chiffre d''affaires du jour et cumul', 'Le chiffre d''affaires d''un jour est la somme de `qty * price` de toutes les lignes de toutes les commandes de ce jour. Pour chaque jour ayant au moins une ligne commandée, renvoyez le chiffre du jour et le cumul (somme des chiffres de ce jour et de tous les jours précédents).
Colonnes, dans cet ordre : `order_date`, chiffre du jour, cumul.
Triez par `order_date` croissant.', 'CREATE TABLE customers (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    city TEXT NOT NULL
);
CREATE TABLE products (
    id       INTEGER PRIMARY KEY,
    name     TEXT NOT NULL,
    category TEXT NOT NULL,
    price    REAL NOT NULL
);
CREATE TABLE orders (
    id          INTEGER PRIMARY KEY,
    customer_id INTEGER REFERENCES customers(id),
    order_date  TEXT NOT NULL
);
CREATE TABLE order_items (
    order_id   INTEGER NOT NULL REFERENCES orders(id),
    product_id INTEGER NOT NULL REFERENCES products(id),
    qty        INTEGER NOT NULL,
    PRIMARY KEY (order_id, product_id)
);

